B.aCv=new A.cC("\u0906\u092f\u0924 \u0915\u0947 \u092a\u093e\u0938 \u092c\u0941\u0915\u092e\u093e\u0930\u094d\u0915 \u0906\u0907\u0915\u0928 \u0926\u092c\u093e\u0907\u090f, \u092f\u093e \u0906\u092f\u0924 \u0915\u094b \u0926\u0947\u0930 \u0924\u0915 \u0926\u092c\u093e\u0907\u090f: \u0939\u0935\u093e\u0932\u0947 \u0915\u0947 \u0938\u093e\u0925 \u0915\u0949\u092a\u0940, \u092f\u093e \u0917\u093c\u0932\u0924\u0940 \u092c\u0924\u093e\u0907\u090f\u0964 \u0916\u094b\u091c \u092e\u0947\u0902 \u0905\u0930\u092c\u0940, \u0909\u0930\u094d\u0926\u0942, \u0938\u0942\u0930\u0924 \u0915\u093e \u0928\u093e\u092e \u0915\u093f\u0938\u0940 \u092d\u0940 \u0938\u094d\u092a\u0947\u0932\u093f\u0902\u0917 \u092e\u0947\u0902 (yasin, yaseen) \u092f\u093e \u0939\u0935\u093e\u0932\u093e \u091c\u0948\u0938\u0947 36:1 \u0932\u093f\u0916\u093f\u090f\u0964","\u092c\u0941\u0915\u092e\u093e\u0930\u094d\u0915, \u0915\u0949\u092a\u0940 \u0914\u0930 \u0916\u094b\u091c")
B.aCo=new A.cC("\u0924\u0930\u094d\u091c\u0941\u092e\u093e \u0924\u092d\u0940 \u0926\u093f\u0916\u0947\u0917\u093e \u091c\u092c \u0939\u092e\u093e\u0930\u0947 \u0909\u0932\u092e\u093e \u0909\u0938\u0915\u0947 \u0938\u094d\u0930\u094b\u0924 \u0915\u0940 \u0924\u0938\u094d\u0926\u0940\u0915\u093c \u0915\u0930 \u0926\u0947\u0902\u0917\u0947\u0964 \u0924\u092c \u0924\u0915 \u092a\u0922\u093c\u0928\u0947 \u0935\u093e\u0932\u0947 \u092a\u0947\u091c \u092a\u0930 \u090f\u0915 \u0928\u094b\u091f \u0926\u093f\u0916\u0924\u093e \u0939\u0948\u0964","\u0924\u0930\u094d\u091c\u0941\u092e\u093e")
B.aCC=new A.cC('\u0905\u092a\u0928\u093e \u0936\u0939\u0930 \u091a\u0941\u0928\u093f\u090f \u092f\u093e "\u092e\u0947\u0930\u0940 \u0905\u092d\u0940 \u0915\u0940 \u091c\u0917\u0939 \u0932\u0940\u091c\u093f\u090f" \u0926\u092c\u093e\u0907\u090f\u0964 \u0939\u093f\u0938\u093e\u092c \u092f\u0942\u0928\u093f\u0935\u0930\u094d\u0938\u093f\u091f\u0940 \u0911\u092b\u093c \u0907\u0938\u094d\u0932\u093e\u092e\u093f\u0915 \u0938\u093e\u0907\u0902\u0938\u0947\u091c\u093c, \u0915\u0930\u093e\u091a\u0940 \u0914\u0930 \u0939\u0928\u092b\u093c\u0940 \u0905\u0938\u094d\u0930 \u0915\u0947 \u0905\u0928\u0941\u0938\u093e\u0930 \u0939\u0948\u0964 \u090f\u0921\u0935\u093e\u0902\u0938 \u092e\u094b\u0921 (\u0938\u0947\u091f\u093f\u0902\u0917\u094d\u0938 \u092e\u0947\u0902 \u0906\u0938\u093e\u0928 \u092e\u094b\u0921 \u092c\u0902\u0926 \u0915\u0930\u0915\u0947) \u092e\u0947\u0902 \u0939\u0930 \u0935\u0915\u093c\u094d\u0924 \u0915\u094b \u0915\u0941\u091b \u092e\u093f\u0928\u091f \u0906\u0917\u0947-\u092a\u0940\u091b\u0947 \u0915\u0930\u0915\u0947 \u0905\u092a\u0928\u0940 \u092e\u0938\u094d\u091c\u093f\u0926 \u0938\u0947 \u092e\u093f\u0932\u093e \u0938\u0915\u0924\u0947 \u0939\u0948\u0902\u0964 \u091a\u093e\u0901\u0926 \u0926\u093f\u0916\u0928\u0947 \u092e\u0947\u0902 \u092b\u093c\u0930\u094d\u0915\u093c \u0939\u094b \u0924\u094b \u0939\u093f\u091c\u0930\u0940 \u0924\u093e\u0930\u0940\u0916\u093c \xb12 \u0926\u093f\u0928 \u092c\u0926\u0932\u093f\u090f\u0964',"\u0928\u092e\u093e\u091c\u093c \u0915\u0947 \u0935\u0915\u093c\u094d\u0924")
B.aCk=new A.cC('\u092f\u093e\u0926-\u0926\u0939\u093e\u0928\u0940 \u0938\u093f\u0930\u094d\u092b\u093c \u0935\u093e\u0907\u092c\u094d\u0930\u0947\u091f \u0915\u0930\u0924\u0940 \u0939\u0948\u0964 \u090f\u0902\u0921\u094d\u0930\u0949\u092f\u0921 \u092a\u0930 "Alarms & reminders" \u0915\u0940 \u0907\u091c\u093e\u091c\u093c\u0924 \u0926\u0940\u091c\u093f\u090f \u0914\u0930 \u0907\u0938 \u0910\u092a \u0915\u093e \u092c\u0948\u091f\u0930\u0940 \u0911\u092a\u094d\u091f\u093f\u092e\u093e\u0907\u091c\u093c\u0947\u0936\u0928 \u092c\u0902\u0926 \u0915\u0940\u091c\u093f\u090f\u0964 Xiaomi, Redmi, Oppo, Vivo, Realme \u0914\u0930 \u0915\u0941\u091b Samsung \u092b\u093c\u094b\u0928 \u092e\u0947\u0902 "Autostart" \u091a\u093e\u0932\u0942 \u0915\u0940\u091c\u093f\u090f \u0914\u0930 \u092c\u0948\u091f\u0930\u0940 \u0915\u094b "No restrictions" \u092a\u0930 \u0930\u0916\u093f\u090f, \u0935\u0930\u0928\u093e \u092b\u093c\u094b\u0928 \u092f\u093e\u0926-\u0926\u0939\u093e\u0928\u0940 \u0930\u094b\u0915 \u0938\u0915\u0924\u093e \u0939\u0948\u0964',"\u092f\u093e\u0926-\u0926\u0939\u093e\u0928\u0940 \u0928\u0939\u0940\u0902 \u092c\u091c \u0930\u0939\u0940?")
B.aBP=new A.cC("\u092b\u093c\u094b\u0928 \u0915\u094b \u0938\u092e\u0924\u0932 \u0930\u0916\u093f\u090f \u0914\u0930 \u0932\u094b\u0939\u0947, \u091a\u0941\u0902\u092c\u0915 \u0914\u0930 \u092c\u093f\u091c\u0932\u0940 \u0915\u0947 \u0924\u093e\u0930\u094b\u0902 \u0938\u0947 \u0926\u0942\u0930 \u0930\u0916\u093f\u090f\u0964 \u0924\u0940\u0930 \u0917\u093c\u0932\u0924 \u0932\u0917\u0947 \u0924\u094b \u092b\u093c\u094b\u0928 \u0915\u094b 8 \u0915\u0947 \u0906\u0915\u093e\u0930 \u092e\u0947\u0902 \u0915\u0941\u091b \u092c\u093e\u0930 \u0918\u0941\u092e\u093e\u0907\u090f\u0964 \u0909\u0924\u094d\u0924\u0930 \u0938\u0947 \u0915\u094b\u0923 \u092d\u0940 \u0932\u093f\u0916\u093e \u0939\u094b\u0924\u093e \u0939\u0948, \u0915\u093f\u0938\u0940 \u092d\u0940 \u0915\u092e\u094d\u092a\u093e\u0938 \u0938\u0947 \u0926\u0947\u0916 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902\u0964","\u0915\u093c\u093f\u092c\u0932\u093e")
B.aCN=new A.cC("\u0924\u0938\u094d\u092c\u0940\u0939: \u0917\u093f\u0928\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0915\u0939\u0940\u0902 \u092d\u0940 \u091f\u0948\u092a \u0915\u0940\u091c\u093f\u090f; \u0932\u0915\u094d\u0937\u094d\u092f 33, 99, 100 \u092f\u093e 1000 \u091a\u0941\u0928\u093f\u090f\u0964 \u0928\u092e\u093e\u091c\u093c \u0930\u093f\u0915\u0949\u0930\u094d\u0921: \u0939\u0930 \u0928\u092e\u093e\u091c\u093c \u0915\u094b \u0935\u0915\u093c\u094d\u0924 \u092a\u0930, \u091c\u092e\u093e\u0905\u0924 \u0915\u0947 \u0938\u093e\u0925, \u0915\u093c\u091c\u093c\u093e \u092f\u093e \u091b\u0942\u091f \u0917\u0908 \u091a\u093f\u0939\u094d\u0928\u093f\u0924 \u0915\u0940\u091c\u093f\u090f\u0964 \u092f\u0939 \u0930\u093f\u0915\u0949\u0930\u094d\u0921 \u0938\u093f\u0930\u094d\u092b\u093c \u0906\u092a\u0915\u0947 \u092b\u093c\u094b\u0928 \u092e\u0947\u0902 \u0930\u0939\u0924\u093e \u0939\u0948, \u0915\u092d\u0940 \u0936\u0947\u092f\u0930 \u092f\u093e \u0924\u0941\u0932\u0928\u093e \u0928\u0939\u0940\u0902 \u0939\u094b\u0924\u093e\u0964","\u0924\u0938\u094d\u092c\u0940\u0939 \u0914\u0930 \u0928\u092e\u093e\u091c\u093c \u0930\u093f\u0915\u0949\u0930\u094d\u0921")
B.aCM=new A.cC("\u0915\u094b\u0908 \u0935\u093f\u091c\u094d\u091e\u093e\u092a\u0928 \u0928\u0939\u0940\u0902, \u0921\u0947\u091f\u093e \u092c\u0947\u091a\u0928\u093e \u0928\u0939\u0940\u0902\u0964 \u0906\u092a\u0915\u0940 \u091c\u0917\u0939 \u0938\u093f\u0930\u094d\u092b\u093c \u092b\u093c\u094b\u0928 \u092a\u0930 \u0935\u0915\u093c\u094d\u0924 \u0928\u093f\u0915\u093e\u0932\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0907\u0938\u094d\u0924\u0947\u092e\u093e\u0932 \u0939\u094b\u0924\u0940 \u0939\u0948\u0964 \u0938\u0947\u091f\u093f\u0902\u0917\u094d\u0938, \u092c\u0941\u0915\u092e\u093e\u0930\u094d\u0915 \u0914\u0930 \u0928\u092e\u093e\u091c\u093c \u0930\u093f\u0915\u0949\u0930\u094d\u0921 \u0907\u0938\u0940 \u092b\u093c\u094b\u0928 \u092e\u0947\u0902 \u0930\u0939\u0924\u0947 \u0939\u0948\u0902\u0964","\u0928\u093f\u091c\u0924\u093e")
B.aCE=new A.cC("\u0938\u0947\u091f\u093f\u0902\u0917\u094d\u0938 \u2192 \u0910\u092a \u0915\u0947 \u092c\u093e\u0930\u0947 \u092e\u0947\u0902 \u0914\u0930 \u0938\u094d\u0930\u094b\u0924 \u092e\u0947\u0902 \u0939\u0930 \u0907\u092c\u093e\u0930\u0924 \u0915\u093e \u0938\u094d\u0930\u094b\u0924, \u0909\u0938\u0915\u093e \u0932\u093e\u0907\u0938\u0947\u0902\u0938 \u0914\u0930 \u0910\u092a \u0915\u093e \u0907\u0932\u094d\u092e\u0940 \u092e\u0947\u092f\u093e\u0930 \u0932\u093f\u0916\u093e \u0939\u0948\u0964 \u0915\u094b\u0908 \u0917\u093c\u0932\u0924\u0940 \u092e\u093f\u0932\u0947 \u0924\u094b \u0906\u092f\u0924 \u0915\u094b \u0926\u0947\u0930 \u0924\u0915 \u0926\u092c\u093e\u0907\u090f \u2192 \u0917\u093c\u0932\u0924\u0940 \u092c\u0924\u093e\u0907\u090f\u0964","\u0938\u094d\u0930\u094b\u0924 \u0914\u0930 \u0917\u093c\u0932\u0924\u093f\u092f\u093e\u0901")
B.aol=s([B.aBV,B.aC8,B.aCv,B.aCo,B.aCC,B.aCk,B.aBP,B.aCN,B.aCM,B.aCE],t.pT)
B.aCe=new A.cC("\u0627\u067e\u0646\u06cc \u0632\u0628\u0627\u0646\u060c \u0627\u067e\u0646\u0627 \u0634\u06c1\u0631 \u0627\u0648\u0631 \u0627\u06cc\u067e \u06a9\u06d2 \u0648\u06c1 \u062d\u0635\u06d2 \u0645\u0646\u062a\u062e\u0628 \u06a9\u06cc\u062c\u06cc\u06d2 \u062c\u0648 \u0622\u067e \u06a9\u0648 \u0686\u0627\u06c1\u06cc\u06cc\u06ba\u06d4 \u06c1\u0648\u0645 \u067e\u0631 \u0635\u0631\u0641 \u0648\u06c1\u06cc \u062f\u06a9\u06be\u06d2 \u06af\u0627\u06d4 \u0628\u0639\u062f \u0645\u06cc\u06ba \u062a\u0631\u062a\u06cc\u0628\u0627\u062a \u2190 \u0645\u0627\u0688\u06cc\u0648\u0644 \u0645\u06cc\u06ba \u06a9\u0628\u06be\u06cc \u0628\u06be\u06cc \u0628\u062f\u0644 \u0633\u06a9\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4 \u0627\u06cc\u067e \u0627\u0646\u0679\u0631\u0646\u06cc\u0679 \u06a9\u06d2 \u0628\u063a\u06cc\u0631 \u0628\u06be\u06cc \u0686\u0644\u062a\u06cc \u06c1\u06d2\u06d4","\u0622\u063a\u0627\u0632")
B.aD1=new A.cC('\u0642\u0631\u0622\u0646 \u06a9\u06be\u0648\u0644\u06cc\u06d2 \u2190 \u0633\u0648\u0631\u062a \u06cc\u0627 \u067e\u0627\u0631\u06c1 \u0645\u0646\u062a\u062e\u0628 \u06a9\u06cc\u062c\u06cc\u06d2\u06d4 \u067e\u0691\u06be\u0646\u06d2 \u06a9\u06cc \u062a\u0631\u062a\u06cc\u0628\u0627\u062a (\u0633\u0644\u0627\u0626\u06cc\u0688\u0631 \u0648\u0627\u0644\u0627 \u0622\u0626\u06cc\u06a9\u0646) \u0645\u06cc\u06ba \u0627\u0646\u0688\u0648 \u067e\u0627\u06a9 \u06cc\u0627 \u0639\u062b\u0645\u0627\u0646\u06cc \u062e\u0637 \u0645\u0646\u062a\u062e\u0628 \u06a9\u06cc\u062c\u06cc\u06d2 \u0627\u0648\u0631 \u062d\u0631\u0648\u0641 \u0628\u0691\u06d2 \u06a9\u06cc\u062c\u06cc\u06d2\u06d4 \u06c1\u0631 \u0622\u06cc\u062a \u06a9\u06d2 \u0633\u0627\u062a\u06be \u0627\u0633 \u06a9\u0627 \u062d\u0648\u0627\u0644\u06c1 (\u062c\u06cc\u0633\u06d2 2:255) \u062f\u06a9\u06be\u062a\u0627 \u06c1\u06d2\u06d4 \u0627\u06cc\u067e \u06cc\u0627\u062f \u0631\u06a9\u06be\u062a\u06cc \u06c1\u06d2 \u06a9\u06c1 \u0622\u067e \u06a9\u06c1\u0627\u06ba \u0631\u06a9\u06d2 \u062a\u06be\u06d2 \u2014 \u06c1\u0648\u0645 \u067e\u0631 "\u062c\u06c1\u0627\u06ba \u0686\u06be\u0648\u0691\u0627 \u062a\u06be\u0627 \u0648\u06c1\u06cc\u06ba \u0633\u06d2 \u067e\u0691\u06be\u06cc\u06d2" \u062f\u0628\u0627\u0626\u06cc\u06d2\u06d4',"\u0642\u0631\u0622\u0646 \u067e\u0691\u06be\u0646\u0627")
B.aCG=new A.cC("\u0622\u06cc\u062a \u06a9\u06d2 \u067e\u0627\u0633 \u0628\u064f\u06a9 \u0645\u0627\u0631\u06a9 \u06a9\u0627 \u0622\u0626\u06cc\u06a9\u0646 \u062f\u0628\u0627\u0626\u06cc\u06d2\u060c \u06cc\u0627 \u0622\u06cc\u062a \u06a9\u0648 \u062f\u06cc\u0631 \u062a\u06a9 \u062f\u0628\u0627\u0626\u06cc\u06d2: \u062d\u0648\u0627\u0644\u06d2 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u06a9\u0627\u067e\u06cc\u060c \u06cc\u0627 \u063a\u0644\u0637\u06cc \u06a9\u06cc \u0627\u0637\u0644\u0627\u0639\u06d4 \u062a\u0644\u0627\u0634 \u0645\u06cc\u06ba \u0639\u0631\u0628\u06cc\u060c \u0627\u0631\u062f\u0648\u060c \u0633\u0648\u0631\u062a \u06a9\u0627 \u0646\u0627\u0645 \u06a9\u0633\u06cc \u0628\u06be\u06cc \u06c1\u062c\u06d2 \u0645\u06cc\u06ba (yasin, yaseen) \u06cc\u0627 \u062d\u0648\u0627\u0644\u06c1 \u062c\u06cc\u0633\u06d2 36:1 \u0644\u06a9\u06be\u06cc\u06d2\u06d4","\u0628\u064f\u06a9 \u0645\u0627\u0631\u06a9\u060c \u06a9\u0627\u067e\u06cc \u0627\u0648\u0631 \u062a\u0644\u0627\u0634")
B.aCX=new A.cC("\u062a\u0631\u062c\u0645\u06c1 \u062a\u0628\u06be\u06cc \u062f\u06a9\u06be\u06d2 \u06af\u0627 \u062c\u0628 \u06c1\u0645\u0627\u0631\u06d2 \u0639\u0644\u0645\u0627\u0621 \u0627\u0633 \u06a9\u06d2 \u0645\u0627\u062e\u0630 \u06a9\u06cc \u062a\u0635\u062f\u06cc\u0642 \u06a9\u0631 \u062f\u06cc\u06ba \u06af\u06d2\u06d4 \u062a\u0628 \u062a\u06a9 \u067e\u0691\u06be\u0646\u06d2 \u0648\u0627\u0644\u06d2 \u0635\u0641\u062d\u06d2 \u067e\u0631 \u0627\u06cc\u06a9 \u0646\u0648\u0679 \u062f\u06a9\u06be\u062a\u0627 \u06c1\u06d2\u06d4","\u062a\u0631\u062c\u0645\u06c1")
B.aCP=new A.cC('\u0627\u067e\u0646\u0627 \u0634\u06c1\u0631 \u0645\u0646\u062a\u062e\u0628 \u06a9\u06cc\u062c\u06cc\u06d2 \u06cc\u0627 "\u0645\u06cc\u0631\u0627 \u0645\u0648\u062c\u0648\u062f\u06c1 \u0645\u0642\u0627\u0645 \u0644\u06cc\u062c\u06cc\u06d2" \u062f\u0628\u0627\u0626\u06cc\u06d2\u06d4 \u062d\u0633\u0627\u0628 \u06cc\u0648\u0646\u06cc\u0648\u0631\u0633\u0679\u06cc \u0622\u0641 \u0627\u0633\u0644\u0627\u0645\u06a9 \u0633\u0627\u0626\u0646\u0633\u0632\u060c \u06a9\u0631\u0627\u0686\u06cc \u0627\u0648\u0631 \u062d\u0646\u0641\u06cc \u0639\u0635\u0631 \u06a9\u06d2 \u0645\u0637\u0627\u0628\u0642 \u06c1\u06d2\u06d4 \u0627\u06cc\u0688\u0648\u0627\u0646\u0633 \u0645\u0648\u0688 (\u062a\u0631\u062a\u06cc\u0628\u0627\u062a \u0645\u06cc\u06ba \u0622\u0633\u0627\u0646 \u0645\u0648\u0688 \u0628\u0646\u062f \u06a9\u0631 \u06a9\u06d2) \u0645\u06cc\u06ba \u06c1\u0631 \u0648\u0642\u062a \u06a9\u0648 \u0686\u0646\u062f \u0645\u0646\u0679 \u0622\u06af\u06d2 \u067e\u06cc\u0686\u06be\u06d2 \u06a9\u0631 \u06a9\u06d2 \u0627\u067e\u0646\u06cc \u0645\u0633\u062c\u062f \u0633\u06d2 \u0645\u0644\u0627 \u0633\u06a9\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4 \u0631\u0624\u06cc\u062a\u0650 \u06c1\u0644\u0627\u0644 \u0645\u06cc\u06ba \u0641\u0631\u0642 \u06c1\u0648 \u062a\u0648 \u06c1\u062c\u0631\u06cc \u062a\u0627\u0631\u06cc\u062e \xb12 \u062f\u0646 \u0628\u062f\u0644\u06cc\u06d2\u06d4',"\u0627\u0648\u0642\u0627\u062a\u0650 \u0646\u0645\u0627\u0632")
B.aC6=new A.cC('\u06cc\u0627\u062f \u062f\u06c1\u0627\u0646\u06cc \u0635\u0631\u0641 \u0648\u0627\u0626\u0628\u0631\u06cc\u0679 \u06a9\u0631\u062a\u06cc \u06c1\u06d2\u06d4 \u0627\u06cc\u0646\u0688\u0631\u0627\u0626\u06cc\u0688 \u067e\u0631 "Alarms & reminders" \u06a9\u06cc \u0627\u062c\u0627\u0632\u062a \u062f\u06cc\u062c\u06cc\u06d2 \u0627\u0648\u0631 \u0627\u0633 \u0627\u06cc\u067e \u06a9\u06cc \u0628\u06cc\u0679\u0631\u06cc \u0622\u067e\u0679\u06cc\u0645\u0627\u0626\u0632\u06cc\u0634\u0646 \u0628\u0646\u062f \u06a9\u06cc\u062c\u06cc\u06d2\u06d4 Xiaomi\u060c Redmi\u060c Oppo\u060c Vivo\u060c Realme \u0627\u0648\u0631 \u0628\u0639\u0636 Samsung \u0641\u0648\u0646\u0632 \u0645\u06cc\u06ba "Autostart" \u0622\u0646 \u06a9\u06cc\u062c\u06cc\u06d2 \u0627\u0648\u0631 \u0628\u06cc\u0679\u0631\u06cc \u06a9\u0648 "No restrictions" \u067e\u0631 \u0631\u06a9\u06be\u06cc\u06d2\u060c \u0648\u0631\u0646\u06c1 \u0641\u0648\u0646 \u06cc\u0627\u062f \u062f\u06c1\u0627\u0646\u06cc \u0631\u0648\u06a9 \u0633\u06a9\u062a\u0627 \u06c1\u06d2\u06d4',"\u06cc\u0627\u062f \u062f\u06c1\u0627\u0646\u06cc \u0646\u06c1\u06cc\u06ba \u0628\u062c \u0631\u06c1\u06cc\u061f")
B.aCr=new A.cC("\u0641\u0648\u0646 \u06a9\u0648 \u0633\u06cc\u062f\u06be\u0627 \u0631\u06a9\u06be\u06cc\u06d2 \u0627\u0648\u0631 \u0644\u0648\u06c1\u06d2\u060c \u0645\u0642\u0646\u0627\u0637\u06cc\u0633 \u0627\u0648\u0631 \u0628\u062c\u0644\u06cc \u06a9\u06d2 \u062a\u0627\u0631\u0648\u06ba \u0633\u06d2 \u062f\u0648\u0631 \u0631\u06a9\u06be\u06cc\u06d2\u06d4 \u062a\u06cc\u0631 \u063a\u0644\u0637 \u0644\u06af\u06d2 \u062a\u0648 \u0641\u0648\u0646 \u06a9\u0648 \u06f8 \u06a9\u06cc \u0634\u06a9\u0644 \u0645\u06cc\u06ba \u0686\u0646\u062f \u0628\u0627\u0631 \u06af\u06be\u0645\u0627\u0626\u06cc\u06d2\u06d4 \u0634\u0645\u0627\u0644 \u0633\u06d2 \u0632\u0627\u0648\u06cc\u06c1 \u0628\u06be\u06cc \u0644\u06a9\u06be\u0627 \u06c1\u0648\u062a\u0627 \u06c1\u06d2\u060c \u06a9\u0633\u06cc \u0628\u06be\u06cc \u06a9\u0645\u067e\u0627\u0633 \u0633\u06d2 \u062f\u06cc\u06a9\u06be \u0633\u06a9\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4","\u0642\u0628\u0644\u06c1")
B.aCK=new A.cC("\u062a\u0633\u0628\u06cc\u062d: \u06af\u0646\u0646\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2 \u06a9\u06c1\u06cc\u06ba \u0628\u06be\u06cc \u0679\u06cc\u067e \u06a9\u06cc\u062c\u06cc\u06d2\u061b \u06c1\u062f\u0641 33\u060c 99\u060c 100 \u06cc\u0627 1000 \u0645\u0646\u062a\u062e\u0628 \u06a9\u06cc\u062c\u06cc\u06d2\u06d4 \u0646\u0645\u0627\u0632 \u06a9\u0627 \u0631\u06cc\u06a9\u0627\u0631\u0688: \u06c1\u0631 \u0646\u0645\u0627\u0632 \u06a9\u0648 \u0648\u0642\u062a \u067e\u0631\u060c \u062c\u0645\u0627\u0639\u062a \u06a9\u06d2 \u0633\u0627\u062a\u06be\u060c \u0642\u0636\u0627 \u06cc\u0627 \u0686\u06be\u0648\u0679 \u06af\u0626\u06cc \u06a9\u0627 \u0646\u0634\u0627\u0646 \u0644\u06af\u0627\u0626\u06cc\u06d2\u06d4 \u06cc\u06c1 \u0631\u06cc\u06a9\u0627\u0631\u0688 \u0635\u0631\u0641 \u0622\u067e \u06a9\u06d2 \u0641\u0648\u0646 \u0645\u06cc\u06ba \u0631\u06c1\u062a\u0627 \u06c1\u06d2\u060c \u06a9\u0628\u06be\u06cc \u0634\u06cc\u0626\u0631 \u06cc\u0627 \u0645\u0648\u0627\u0632\u0646\u06c1 \u0646\u06c1\u06cc\u06ba \u06c1\u0648\u062a\u0627\u06d4","\u062a\u0633\u0628\u06cc\u062d \u0627\u0648\u0631 \u0646\u0645\u0627\u0632 \u06a9\u0627 \u0631\u06cc\u06a9\u0627\u0631\u0688")
B.aCS=new A.cC("\u06a9\u0648\u0626\u06cc \u0627\u0634\u062a\u06c1\u0627\u0631 \u0646\u06c1\u06cc\u06ba\u060c \u0688\u06cc\u0679\u0627 \u06a9\u06cc \u0641\u0631\u0648\u062e\u062a \u0646\u06c1\u06cc\u06ba\u06d4 \u0622\u067e \u06a9\u0627 \u0645\u0642\u0627\u0645 \u0635\u0631\u0641 \u0641\u0648\u0646 \u067e\u0631 \u0627\u0648\u0642\u0627\u062a \u0646\u06a9\u0627\u0644\u0646\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u06c1\u0648\u062a\u0627 \u06c1\u06d2\u06d4 \u062a\u0631\u062a\u06cc\u0628\u0627\u062a\u060c \u0628\u064f\u06a9 \u0645\u0627\u0631\u06a9 \u0627\u0648\u0631 \u0646\u0645\u0627\u0632 \u06a9\u0627 \u0631\u06cc\u06a9\u0627\u0631\u0688 \u0627\u0633\u06cc \u0641\u0648\u0646 \u0645\u06cc\u06ba \u0631\u06c1\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4","\u0631\u0627\u0632\u062f\u0627\u0631\u06cc")
B.aC1=new A.cC("\u062a\u0631\u062a\u06cc\u0628\u0627\u062a \u2190 \u062a\u0639\u0627\u0631\u0641 \u0627\u0648\u0631 \u0645\u0627\u062e\u0630 \u0645\u06cc\u06ba \u06c1\u0631 \u0639\u0628\u0627\u0631\u062a \u06a9\u0627 \u0645\u0627\u062e\u0630\u060c \u0627\u0633 \u06a9\u0627 \u0644\u0627\u0626\u0633\u0646\u0633 \u0627\u0648\u0631 \u0627\u06cc\u067e \u06a9\u0627 \u0639\u0644\u0645\u06cc \u0645\u0639\u06cc\u0627\u0631 \u0644\u06a9\u06be\u0627 \u06c1\u06d2\u06d4 \u06a9\u0648\u0626\u06cc \u063a\u0644\u0637\u06cc \u0645\u0644\u06d2 \u062a\u0648 \u0622\u06cc\u062a \u06a9\u0648 \u062f\u06cc\u0631 \u062a\u06a9 \u062f\u0628\u0627\u0626\u06cc\u06d2 \u2190 \u063a\u0644\u0637\u06cc \u06a9\u06cc \u0627\u0637\u0644\u0627\u0639 \u062f\u06cc\u062c\u06cc\u06d2\u06d4","\u0645\u0627\u062e\u0630 \u0627\u0648\u0631 \u063a\u0644\u0637\u06cc\u0627\u06ba")
B.apW=s([B.aCe,B.aD1,B.aCG,B.aCX,B.aCP,B.aC6,B.aCr,B.aCK,B.aCS,B.aC1],t.pT)
B.aC_=new A.cC("\u0627\u062e\u062a\u0631 \u0644\u063a\u062a\u0643 \u0648\u0645\u062f\u064a\u0646\u062a\u0643 \u0648\u0623\u0642\u0633\u0627\u0645 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0627\u0644\u062a\u064a \u062a\u0631\u064a\u062f\u0647\u0627\u060c \u0641\u062a\u0639\u0631\u0636 \u0627\u0644\u0634\u0627\u0634\u0629 \u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629 \u0645\u0627 \u0627\u062e\u062a\u0631\u062a\u0647 \u0641\u0642\u0637. \u064a\u0645\u0643\u0646\u0643 \u0627\u0644\u062a\u063a\u064a\u064a\u0631 \u0644\u0627\u062d\u0642\u0627\u064b \u0645\u0646 \u0627\u0644\u0625\u0639\u062f\u0627\u062f\u0627\u062a \u2190 \u0627\u0644\u0623\u0642\u0633\u0627\u0645. \u064a\u0639\u0645\u0644 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u062f\u0648\u0646 \u0625\u0646\u062a\u0631\u0646\u062a.","\u0627\u0644\u0628\u062f\u0627\u064a\u0629")
B.aD0=new A.cC('\u0627\u0641\u062a\u062d \u0627\u0644\u0642\u0631\u0622\u0646 \u2190 \u0627\u062e\u062a\u0631 \u0633\u0648\u0631\u0629 \u0623\u0648 \u062c\u0632\u0621\u0627\u064b. \u0645\u0646 \u0625\u0639\u062f\u0627\u062f\u0627\u062a \u0627\u0644\u0642\u0631\u0627\u0621\u0629 (\u0623\u064a\u0642\u0648\u0646\u0629 \u0627\u0644\u0645\u0646\u0632\u0644\u0642\u0627\u062a) \u0627\u062e\u062a\u0631 \u0627\u0644\u0631\u0633\u0645 \u0627\u0644\u0647\u0646\u062f\u064a \u0627\u0644\u0628\u0627\u0643\u0633\u062a\u0627\u0646\u064a \u0623\u0648 \u0627\u0644\u0639\u062b\u0645\u0627\u0646\u064a \u0648\u0643\u0628\u0651\u0631 \u0627\u0644\u062e\u0637. \u064a\u0638\u0647\u0631 \u0645\u0631\u062c\u0639 \u0643\u0644 \u0622\u064a\u0629 \u0645\u062b\u0644 2:255. \u0648\u064a\u062a\u0630\u0643\u0631 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0645\u0648\u0636\u0639 \u062a\u0648\u0642\u0641\u0643: \u0627\u0636\u063a\u0637 "\u062a\u0627\u0628\u0639 \u0627\u0644\u0642\u0631\u0627\u0621\u0629" \u0641\u064a \u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629.',"\u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0642\u0631\u0622\u0646")
B.aBJ=new A.cC("\u0627\u0636\u063a\u0637 \u0623\u064a\u0642\u0648\u0646\u0629 \u0627\u0644\u0639\u0644\u0627\u0645\u0629 \u0628\u062c\u0627\u0646\u0628 \u0627\u0644\u0622\u064a\u0629\u060c \u0623\u0648 \u0627\u0636\u063a\u0637 \u0645\u0637\u0648\u0644\u0627\u064b \u0639\u0644\u0649 \u0627\u0644\u0622\u064a\u0629 \u0644\u062e\u064a\u0627\u0631\u0627\u062a \u0623\u062e\u0631\u0649: \u0627\u0644\u0646\u0633\u062e \u0645\u0639 \u0627\u0644\u0645\u0631\u062c\u0639 \u0623\u0648 \u0627\u0644\u0625\u0628\u0644\u0627\u063a \u0639\u0646 \u062e\u0637\u0623. \u064a\u0642\u0628\u0644 \u0627\u0644\u0628\u062d\u062b \u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0623\u0631\u062f\u064a\u0629 \u0648\u0627\u0633\u0645 \u0627\u0644\u0633\u0648\u0631\u0629 \u0628\u0623\u064a \u062a\u0647\u062c\u0626\u0629 \u0634\u0627\u0626\u0639\u0629 \u0623\u0648 \u0645\u0631\u062c\u0639\u0627\u064b \u0645\u062b\u0644 36:1.","\u0627\u0644\u0639\u0644\u0627\u0645\u0627\u062a \u0648\u0627\u0644\u0646\u0633\u062e \u0648\u0627\u0644\u0628\u062d\u062b")
